using UnityEngine;
namespace AbujaLife.World { public sealed class TrafficDensityController:MonoBehaviour { public GameObject[] vehiclePrefabs; public Transform[] spawnPoints; public int daytimeCount=30, nighttimeCount=16; public DayNightCycle clock; public float refreshSeconds=10f; float next; void Update(){if(Time.time<next)return;next=Time.time+refreshSeconds;int target=(clock&&clock.hour>=20||clock&&clock.hour<6)?nighttimeCount:daytimeCount;int current=transform.childCount;for(int i=current;i<target&&spawnPoints.Length>0&&vehiclePrefabs.Length>0;i++){var s=spawnPoints[Random.Range(0,spawnPoints.Length)];Instantiate(vehiclePrefabs[Random.Range(0,vehiclePrefabs.Length)],s.position,s.rotation,transform);}for(int i=current-1;i>=target;i--)Destroy(transform.GetChild(i).gameObject);} } }
